function fBul(id){var F=firmalar();for(var i=0;i<F.length;i++)if(F[i].id===id)return F[i];return null}
function uBul(F,ad){if(!F)return null;for(var i=0;i<F.u.length;i++)if(F.u[i].ad===ad)return F.u[i];return null}
