function mik(x){return x.dk?f(x.a,x.a%1?2:0)+" ton dökme":f(x.a,0)+" çuval"}
function bfy(x){return x.dk?tl(x.p)+"/ton":f(x.p,0)+" TL"}
function topMik(g){var L=[];if(g.cuv)L.push(f(g.cuv,0)+" çuval");if(g.dton)L.push(f(g.dton,g.dton%1?2:0)+" ton dökme");return L.join(" + ")+" ("+f(g.ton,g.ton%1?2:0)+" ton)"}
function degisti(o){o.mod=new Date().toISOString();var h=hesap(o);o.k.forEach(function(x){var g=h.G.filter(function(g){return g.F.id===x.f})[0],u=g&&uBul(g.F,x.ad);if(u){x.bf=o.od==="k"?u.k:u.n;x.fad=g.F.ad}});o.top=h.T.top;o.cuv=h.T.cuv;try{save()}catch(e){}}
