function resimKucult(file,cb){var img=new Image(),url=URL.createObjectURL(file);img.onload=function(){try{var W=img.naturalWidth,H=img.naturalHeight,sc=Math.min(1,2000/Math.max(W,H)),cv=document.createElement("canvas");cv.width=Math.round(W*sc);cv.height=Math.round(H*sc);cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(url);cb(cv.toDataURL("image/jpeg",0.9).split(",")[1])}catch(e){cb(null)}};img.onerror=function(){cb(null)};img.src=url}
